// Active MVP advertising alerts are campaign-level only (ad_weak_campaign_efficiency).
// SKU-level ad spend attribution is not reliable in current sources; SKU-level ad alert types
// are legacy and must not be generated by EvaluateAdvertisingRules.
package alerts

import (
	"fmt"
	"math"
)

const (
	adZeroResultNoiseFloor = 1000.0

	adDRRThresholdMedium   = 0.35
	adDRRThresholdHigh     = 0.50
	adDRRThresholdCritical = 0.80

	adReasonHighDRR                    = "high_drr"
	adReasonSpendWithoutRevenue        = "spend_without_revenue"
	adReasonSpendWithoutOrders         = "spend_without_orders"
	adReasonSpendWithoutRevenueAndOrds = "spend_without_revenue_and_orders"

	adMetricCampaignDRR        = "campaign_drr"
	adMetricCampaignZeroResult = "campaign_zero_result"
)

type AdvertisingRuleEvaluationInput struct {
	SellerAccountID   int64
	DateFrom          string
	DateTo            string
	AsOfDate          string
	CampaignSummaries []AdCampaignMetricSummary
}

type AdvertisingRuleEvaluationResult struct {
	RuleResults []RuleResult
	Skipped     int
}

func EvaluateAdvertisingRules(input AdvertisingRuleEvaluationInput) AdvertisingRuleEvaluationResult {
	results := make([]RuleResult, 0)
	skipped := 0

	for _, campaign := range input.CampaignSummaries {
		if rr, ok := evaluateAdWeakCampaignEfficiency(input, campaign); ok {
			results = append(results, rr)
		} else {
			skipped++
		}
	}

	return AdvertisingRuleEvaluationResult{RuleResults: results, Skipped: skipped}
}

func evaluateAdWeakCampaignEfficiency(input AdvertisingRuleEvaluationInput, campaign AdCampaignMetricSummary) (RuleResult, bool) {
	if campaign.Spend <= 0 {
		return RuleResult{}, false
	}

	metrics := computeCampaignAdMetrics(campaign)

	if campaign.Spend >= adZeroResultNoiseFloor && (campaign.Revenue <= 0 || campaign.Orders <= 0) {
		return buildAdWeakCampaignAlert(input, campaign, metrics, adWeakCampaignZeroResultConfig(campaign))
	}

	if campaign.Revenue > 0 && metrics.DRR != nil && *metrics.DRR >= adDRRThresholdMedium {
		return buildAdWeakCampaignAlert(input, campaign, metrics, adWeakCampaignHighDRRConfig(*metrics.DRR))
	}

	return RuleResult{}, false
}

type adWeakCampaignAlertConfig struct {
	metric   string
	title    string
	message  string
	severity Severity
	urgency  Urgency
	reason   string
	reasons  []string
}

func adWeakCampaignZeroResultConfig(campaign AdCampaignMetricSummary) adWeakCampaignAlertConfig {
	reasons := make([]string, 0, 2)
	reason := adReasonSpendWithoutRevenueAndOrds
	if campaign.Revenue <= 0 && campaign.Orders <= 0 {
		reasons = append(reasons, adReasonSpendWithoutRevenue, adReasonSpendWithoutOrders)
	} else if campaign.Revenue <= 0 {
		reason = adReasonSpendWithoutRevenue
		reasons = append(reasons, adReasonSpendWithoutRevenue)
	} else {
		reason = adReasonSpendWithoutOrders
		reasons = append(reasons, adReasonSpendWithoutOrders)
	}
	return adWeakCampaignAlertConfig{
		metric:   adMetricCampaignZeroResult,
		title:    "Рекламная кампания без подтверждённого результата",
		message:  "Кампания тратит рекламный бюджет, но система не видит подтверждённой рекламной выручки и/или заказов.",
		severity: SeverityCritical,
		urgency:  UrgencyHigh,
		reason:   reason,
		reasons:  reasons,
	}
}

func adWeakCampaignHighDRRConfig(drr float64) adWeakCampaignAlertConfig {
	cfg := adWeakCampaignAlertConfig{
		metric:  adMetricCampaignDRR,
		title:   "Слабая эффективность рекламной кампании",
		message: "ДРР кампании выше допустимого порога при наличии подтверждённой выручки.",
		reason:  adReasonHighDRR,
		reasons: []string{adReasonHighDRR},
		urgency: UrgencyMedium,
	}
	switch {
	case drr >= adDRRThresholdCritical:
		cfg.severity = SeverityCritical
		cfg.urgency = UrgencyHigh
	case drr >= adDRRThresholdHigh:
		cfg.severity = SeverityHigh
		cfg.urgency = UrgencyHigh
	default:
		cfg.severity = SeverityMedium
		cfg.urgency = UrgencyMedium
	}
	return cfg
}

func buildAdWeakCampaignAlert(
	input AdvertisingRuleEvaluationInput,
	campaign AdCampaignMetricSummary,
	metrics campaignAdMetrics,
	cfg adWeakCampaignAlertConfig,
) (RuleResult, bool) {
	entityID := fmt.Sprintf("%d", campaign.CampaignExternalID)
	evidence := BuildAdvertisingEvidence(campaign.Spend, campaign.Clicks, campaign.Orders, campaign.Revenue, evidenceDRRPercent(metrics.DRRPercent), EvidencePayload{
		"metric":               cfg.metric,
		"metric_quality":       "actual_campaign_level",
		"campaign_id":          campaign.CampaignExternalID,
		"campaign_external_id": campaign.CampaignExternalID,
		"campaign_name":        campaign.CampaignName,
		"campaign_type":        campaign.CampaignType,
		"spend":                campaign.Spend,
		"revenue":              campaign.Revenue,
		"orders_count":         campaign.Orders,
		"drr":                  evidenceFloatPtr(metrics.DRR),
		"drr_percent":          evidenceFloatPtr(metrics.DRRPercent),
		"cpo":                  evidenceFloatPtr(metrics.CPO),
		"impressions":          campaign.Impressions,
		"clicks":               campaign.Clicks,
		"ctr":                  evidenceFloatPtr(metrics.CTR),
		"cpc":                  evidenceFloatPtr(metrics.CPC),
		"threshold_medium":     adDRRThresholdMedium,
		"threshold_high":       adDRRThresholdHigh,
		"threshold_critical":   adDRRThresholdCritical,
		"noise_floor_spend":    adZeroResultNoiseFloor,
		"reason":               cfg.reason,
		"reasons":              cfg.reasons,
		"date_from":            input.DateFrom,
		"date_to":              input.DateTo,
	})
	return RuleResult{
		AlertType:       AlertTypeAdWeakCampaignEfficiency,
		AlertGroup:      AlertGroupAdvertising,
		EntityType:      EntityTypeCampaign,
		EntityID:        &entityID,
		Title:           cfg.title,
		Message:         cfg.message,
		Severity:        cfg.severity,
		Urgency:         cfg.urgency,
		EvidencePayload: evidence,
	}, true
}

type campaignAdMetrics struct {
	DRR        *float64
	DRRPercent *float64
	CPO        *float64
	CTR        *float64
	CPC        *float64
}

func computeCampaignAdMetrics(campaign AdCampaignMetricSummary) campaignAdMetrics {
	out := campaignAdMetrics{}
	if campaign.Revenue > 0 {
		drr := campaign.Spend / campaign.Revenue
		if !math.IsNaN(drr) && !math.IsInf(drr, 0) {
			out.DRR = &drr
			pct := drr * 100
			out.DRRPercent = &pct
		}
	}
	if campaign.Orders > 0 {
		cpo := campaign.Spend / float64(campaign.Orders)
		if !math.IsNaN(cpo) && !math.IsInf(cpo, 0) {
			out.CPO = &cpo
		}
	}
	if campaign.Impressions > 0 {
		ctr := float64(campaign.Clicks) / float64(campaign.Impressions)
		if !math.IsNaN(ctr) && !math.IsInf(ctr, 0) {
			out.CTR = &ctr
		}
	}
	if campaign.Clicks > 0 {
		cpc := campaign.Spend / float64(campaign.Clicks)
		if !math.IsNaN(cpc) && !math.IsInf(cpc, 0) {
			out.CPC = &cpc
		}
	}
	return out
}

func evidenceDRRPercent(drrPercent *float64) float64 {
	if drrPercent == nil {
		return 0
	}
	return *drrPercent
}

func evidenceFloatPtr(v *float64) any {
	if v == nil {
		return nil
	}
	return *v
}
